    blurb: "Chiang Mai's most revered temple, perched on a forested ridge above the city behind a 306-step naga staircase, centred on a gleaming gold chedi said to enshrine a relic of the Buddha. A terrace gives sweeping views over the valley.",
    whyItFits: "For travellers who want a single essential cultural and viewpoint stop close to the city, reachable in well under an hour.",
    priceRange: { low: 30, typical: 50, high: 50, currency: "THB", note: "Around 30-50 THB foreigner entry; the funicular to the top costs a little extra." },
    hours: "Roughly 06:00-18:00 daily",
    tips: ["Go early morning to beat both the heat and the tour coaches.", "Dress modestly: shoulders and knees covered, shoes removed at the inner terrace.", "A red songthaew from the city is the standard ride up."],
    scamWarnings: ["Agree the songthaew fare up and down before departing; return pricing is sometimes inflated."],
    rating: 4.7, reviewSources: ["Tripadvisor", "Google Maps consensus", "Lonely Planet"],
    mapQuery: "Wat Phra That Doi Suthep Chiang Mai", coords: { lat: 18.8047, lng: 98.9217 },
