    categories: ["culture"], budgetTier: "low", kidFriendly: true,
    blurb: "The most important and most visited temple on Phuket, famous for the monks Luang Pho Chaem and Luang Pho Chuang who tended the wounded during the 1876 tin-miners' rebellion. The gilded Grand Pagoda enshrines a relic of the Buddha and gives long views over the temple rooftops; the courtyard firecracker kilns pop all day as worshippers give thanks for answered prayers.",
