    tips: ["Swim between the flags and heed red flags — the monsoon-season rip currents here are dangerous and drown swimmers every year.", "Agree jet-ski and sunbed prices in writing before you start.", "Bangla Road is a walk-through spectacle; keep bar tabs short and count your change."],
