    recognition: "The historic quarter of Phuket Town: pastel Sino-Portuguese shophouses along Thalang and Dibuk Roads and the photogenic lane of Soi Romanee, now full of cafés, galleries and street art.",
    categories: ["culture"], budgetTier: "low", kidFriendly: true,
