    whyItFits: "The island's most characterful town wander — heritage architecture, coffee and street art, and easy in any weather.",
    priceRange: { low: 0, typical: 0, high: 0, currency: "THB", note: "Free to wander; museums and cafés charge a little." },
    hours: "Streets open all day; cafés and shops roughly 09:00-18:00",
    tips: ["Start at Soi Romanee and Thalang Road for the best-preserved shophouses and street art.", "The Thai Hua and Peranakannitat museums explain the town's Baba-Nyonya heritage.", "Come on a weekday to see it lived-in; Sunday evening it becomes the Lard Yai walking street."],
