    localName: "ยอดดอยอินทนนท์ · พระมหาธาตุนภเมทนีดล / นภพลภูมิสิริ",
    categories: ["viewpoint", "nature", "culture"], budgetTier: "low",
    kidFriendly: true, activities: ["viewpoint", "walk"],
    blurb: "Doi Inthanon is the highest point in Thailand (about 2,565m) and the scenic climax of the loop's eastern approach through Mae Chaem. A short boardwalk circles the summit's dripping cloud forest, while at km 41.5 the twin royal chedis — Phra Mahathat Napamethanidon and Napaphonphumisiri, built for the 60th birthdays of King Bhumibol and Queen Sirikit — command long views over the ranges from their landscaped terraces. It is genuinely cold at the top, even in the hot season.",
    whyItFits: "The single grandest viewpoint on the loop, reached by paved road and gentle enough for families and grandparents.",
    priceRange: { low: 20, typical: 300, high: 330, currency: "THB", note: "Park entry: foreigners 300 THB, children 150 THB, Thai 20 THB, vehicle 30 THB. Confirm at the gate." },
    hours: "Park roughly 05:30–18:00; come early for clear summit views before the cloud builds.",
    tips: ["Dress warmly — the summit sits around 12°C even in the hot season and colder at dawn.", "The summit boardwalk and pagoda terraces are paved and partly pram-manageable.", "One park ticket covers the pagodas and the waterfalls the same day.", "Descend the far side to Mae Chaem to rejoin Route 108."],
    scamWarnings: [],
