    amenities: ["wifi", "hot-shower", "restaurant"],
    blurb: "Ban Rak Thai (Mae Aw) is a Yunnanese Chinese village set around a small reservoir in tea-terraced hills near the border. Mud-brick guesthouses and lakeside lodges — such as Lee Wine Rak Thai and Chasa — offer simple rooms with lake and tea-field views, and the tea houses pour locally grown oolong and jin xuan (milk oolong) at roughly 40–60 THB a pot. It makes a memorable, cool overnight rather than just a day trip.",
    whyItFits: "A one-of-a-kind cultural overnight on the loop — Yunnanese food, tea tasting and misty lake mornings, and a calm, safe base for families.",
    priceRange: { low: 500, typical: 1200, high: 2500, currency: "THB", note: "Per night for a lakeside room; simpler rooms are cheaper. Book ahead in the cool season. Confirm locally." },
