    recognition: "Village homestays and a lakeside campground at Ban Ruam Thai beside the pine-fringed Pang Ung reservoir, about 40km from Mae Hong Son, busiest in the cold December–February season.",
    localName: "ที่พัก/ลานกางเต็นท์ปางอุ๋ง บ้านรวมไทย · Pang Ung",
    categories: ["stay", "nature"], budgetTier: "low",
    kidFriendly: true, isLocal: true, stayType: "homestay", stayDuration: "short",
    amenities: ["fan", "hot-shower", "restaurant"],
    blurb: "Beside the pine-ringed Pang Ung reservoir, Ban Ruam Thai village runs simple homestays (from around 100–500 THB) and a lakeside campground where you can pitch your own tent or rent one (about 225 THB) for a small per-person fee, with restrooms, showers and cooking areas. Mornings in December–February are famously misty and cold — sometimes near freezing — which is exactly why Thai visitors flock here in winter.",
    whyItFits: "The loop's most atmospheric overnight for families and campers — a safe, gentle lakeside base with woodsmoke, mist and pine right by the water.",
