    hours: "Roughly 08:00-18:00 daily",
    tips: ["Soak only in the marked lower pools; the top source pools are scalding.", "Vendors near the car park sell eggs to cook in the hot channel - a fun stop with kids.", "Keep your park ticket; it can also cover other Huai Nam Dang sights the same day.", "Weekends and cool-season mornings are busiest."],
