    id: "th-ext-udonthani-cash-health-safety", name: "Udon Thani practical: cash, health & the Laos crossing", city: "Udon Thani", country: "th",
    categories: ["health", "money", "info"], budgetTier: "low", kidFriendly: true,
    blurb: "Udon Thani is the medical centre for the whole upper Isaan region and for a steady flow of patients coming across from Laos. Bangkok Hospital Udon is the 180-bed international option with a 24-hour emergency and trauma centre and mobile ICU ambulances; AEK Udon International Hospital, founded in 1970, has a 24-hour emergency department and a pharmacy open around the clock; Udon Thani Hospital is the 1,154-bed public regional hospital.",
    whyItFits: "For anyone heading to or from Vientiane through Nong Khai, Udon Thani is the last place with hospital-grade care and reliable ATMs on the Thai side.",
    priceRange: { low: 0, typical: 0, high: 220, currency: "THB", note: "Foreign-card ATMs typically add about 220 THB per withdrawal. Draw Thai baht here rather than at the border, where rates are worse." },
    hours: "ATMs 24h; hospital emergency departments 24h; AEK Udon pharmacy 24h",
    tips: ["Emergency numbers: 1669 for ambulance and medical, 1155 for Tourist Police, 191 for police.", "AEK Udon's 24-hour pharmacy is the practical answer to a night-time stomach problem without a hospital admission.", "If you are crossing to Laos at Nong Khai, sort cash, SIM top-ups and any prescription refills here - the border town has far less of everything.", "Udon is a genuine Thai city rather than a resort; English drops off quickly outside the hospitals and the malls."],
